const email = $input.item.json;

const from = (email.from || '').toLowerCase();
const subject = (email.subject || '').toLowerCase();
const hasAttachment = email.attachments && email.attachments.length > 0;
const bodyText = email.text || email.html || '';

// Classifier le type d'email
let emailType = 'nouveau_signalement';

// Quitus : email du MOEX avec PDF en pièce jointe
if (
  from.includes('connexionbatiment.fr') ||
  (subject.match(/gpa\s*n[°o]\s*\d+/i) && hasAttachment) ||
  (bodyText.toLowerCase().includes('réserve levée') && hasAttachment) ||
  (bodyText.toLowerCase().includes('reserve levee') && hasAttachment)
) {
  emailType = 'quitus';
}

// Ignorer nos propres emails de relance (loop prevention)
if (subject.includes('[relance') || subject.includes('[urgent —')) {
  emailType = 'ignorer';
}

return {
  json: {
    ...email,
    email_type: emailType,
    from_email: email.from,
    subject_clean: email.subject,
    body_text: bodyText.substring(0, 3000),
    has_attachment: hasAttachment,
    attachment_count: (email.attachments || []).length
  }
};

const idReserve = parseInt($('Claude - Extraire N° Réserve').first().json.output || '0');
const allRows = $input.all();

if (idReserve === 0) {
  return [{ json: { found: false, id_reserve: 0, message: 'Numéro de réserve non trouvé dans email' } }];
}

// Trouver la ligne correspondante
for (let i = 0; i < allRows.length; i++) {
  const row = allRows[i].json;
  if (parseInt(row['N° de réserve']) === idReserve) {
    return [{
      json: {
        found: true,
        row_index: i,
        id_reserve: idReserve,
        statut: row['Statut'],
        nom: row['Nom'],
        lot: row['N° logement'],
        piece: row['Localisation'],
        date_reception: row['Date réception'],
        already_closed: row['Statut'] === 'cloturee'
      }
    }];
  }
}

return [{ json: { found: false, id_reserve: idReserve, message: 'Ligne non trouvée dans Excel' } }];

let aiOutput = $input.item.json.output || '{}';

// Nettoyer la réponse AI (enlever markdown si présent)
aiOutput = aiOutput.replace(/^```json\s*/i, '').replace(/\s*```$/, '').trim();

let aiData;
try {
  aiData = JSON.parse(aiOutput);
} catch(e) {
  // Si parse échoue, retourner une valeur par défaut
  aiData = {
    nom_client: 'INCONNU',
    lot: 'INCONNU',
    batiment: 'INCONNU',
    piece: 'INCONNU',
    description: 'Analyse automatique échouée - traitement manuel requis',
    recevable: false,
    motif_non_recevable: 'Erreur analyse automatique',
    urgence: false,
    entreprise: 'INDETERMINE'
  };
}

const emailData = $('IMAP - Surveiller Boîte GPA').first().json;

return {
  json: {
    ...aiData,
    from_email: emailData.from,
    original_subject: emailData.subject,
    original_body: emailData.text || emailData.html || '',
    has_attachment: emailData.attachments && emailData.attachments.length > 0
  }
};

// Calculer le prochain ID de réserve
const allRows = $input.all();
let maxId = 0;
for (const row of allRows) {
  const id = parseInt(row.json['N° de réserve'] || '0');
  if (id > maxId) maxId = id;
}
const newId = maxId + 1;

// Récupérer les données de l'analyse AI
const aiData = $('Code - Parser Réponse AI').first().json;
const emailData = $('IMAP - Surveiller Boîte GPA').first().json;

// Calculer les dates
const today = new Date();
const isUrgence = aiData.urgence === true;
const daysToAdd = isUrgence ? 7 : 14;
const dateLimite = new Date(today);
dateLimite.setDate(dateLimite.getDate() + daysToAdd);

const formatDate = (d) => d.toLocaleDateString('fr-FR', { day: '2-digit', month: '2-digit', year: 'numeric' });

return [{
  json: {
    id_reserve: newId,
    date_reception: formatDate(today),
    date_limite: formatDate(dateLimite),
    operation: 'ANTOINETTE',
    nom_client: aiData.nom_client,
    lot: aiData.lot,
    batiment: aiData.batiment,
    piece: aiData.piece,
    description: aiData.description,
    entreprise: aiData.entreprise,
    urgence: isUrgence,
    from_email: emailData.from,
    original_subject: emailData.subject,
    original_body: emailData.text || emailData.html || ''
  }
}];
